class LocalStorageAdapter {
  root;
  sessionsDir;
  memoryDir;
  registryDir;
  settingsDir;
  constructor(rootDir = defaultRoot()) {
    this.root = rootDir;
    this.sessionsDir = join3(rootDir, "sessions");
    this.memoryDir = join3(rootDir, "memory");
    this.registryDir = join3(rootDir, "registry");
    this.settingsDir = join3(rootDir, "settings");
  }
  async writeEvent(sessionId, event) {
    await ensureDir(this.sessionsDir);
    const file2 = join3(this.sessionsDir, `${sessionId}.jsonl`);
    await appendFile(file2, JSON.stringify(event) + `
`);
    const meta3 = await this.getSessionMeta(sessionId);
    const updated = {
      ...meta3,
      updatedAt: nowIso()
    };
    await writeJson(join3(this.sessionsDir, `${sessionId}.meta.json`), updated);
  }
  async readEvents(sessionId, options) {
    const file2 = join3(this.sessionsDir, `${sessionId}.jsonl`);
    if (!existsSync3(file2))
      return [];
    const raw = await readFile(file2, "utf-8");
    const lines = raw.split(`
`).filter(Boolean);
    const start = options?.cursor ? Math.max(0, parseInt(options.cursor, 10) || 0) : 0;
    const slice = lines.slice(start);
    const limited = options?.limit ? slice.slice(-options.limit) : slice;
    return limited.map((l) => JSON.parse(l));
  }
  async getSessionMeta(sessionId) {
    await ensureDir(this.sessionsDir);
    const metaPath = join3(this.sessionsDir, `${sessionId}.meta.json`);
    const fallback = {
      sessionId,
      createdAt: nowIso(),
      updatedAt: nowIso(),
      tags: [],
      status: "active"
    };
    const meta3 = await readJson(metaPath, fallback);
    if (!existsSync3(metaPath)) {
      await writeJson(metaPath, meta3);
    }
    return meta3;
  }
  async appendFact(fact) {
    await ensureDir(this.memoryDir);
    const file2 = join3(this.memoryDir, `facts.jsonl`);
    const entry = {
      ...fact,
      createdAt: fact.createdAt ?? nowIso(),
      updatedAt: fact.updatedAt ?? nowIso()
    };
    await appendFile(file2, JSON.stringify(entry) + `
`);
  }
  async queryMemory(query) {
    const file2 = join3(this.memoryDir, `facts.jsonl`);
    if (!existsSync3(file2))
      return [];
    const raw = await readFile(file2, "utf-8");
    const lines = raw.split(`
`).filter(Boolean);
    const q = query.toLowerCase();
    return lines.map((l) => JSON.parse(l)).filter((f) => f.content?.toLowerCase().includes(q) || f.tags?.some((t) => t.toLowerCase().includes(q)));
  }
  async getComponent(id) {
    const all = await this.readComponents();
    const found = all.find((c) => c.componentId === id);
    if (!found)
      throw new Error(`Component not found: ${id}`);
    return found;
  }
  async listComponents(type) {
    const all = await this.readComponents();
    return all.filter((c) => c.type === type);
  }
  async readComponents() {
    await ensureDir(this.registryDir);
    const path4 = join3(this.registryDir, "components.json");
    return await readJson(path4, []);
  }
  async getConfig() {
    await ensureDir(this.settingsDir);
    const path4 = join3(this.settingsDir, "config.json");
    return await readJson(path4, {});
  }
  async setConfig(config2) {
    await ensureDir(this.settingsDir);
    const path4 = join3(this.settingsDir, "config.json");
    const current = await this.getConfig();
    const merged = { ...current, ...config2 };
    await writeJson(path4, merged);
  }
}
async function listLocalSessions(rootDir = defaultRoot()) {
  const dir = join3(rootDir, "sessions");
  if (!existsSync3(dir))
    return [];
  const entries = await readdir(dir);
  return entries.filter((f) => f.endsWith(".jsonl")).map((f) => f.replace(/\.jsonl$/, "")).sort().reverse();
}
async function clearLocalSession(sessionId, rootDir = defaultRoot()) {
  try {
    const dir = join3(rootDir, "sessions");
    const file2 = join3(dir, `${sessionId}.jsonl`);
    const meta3 = join3(dir, `${sessionId}.meta.json`);
    if (!existsSync3(file2) && !existsSync3(meta3))
      return false;
    await ensureDir(dir);
    await writeFile(file2, "");
    return true;
  } catch {
    return false;
  }
}
async function deleteLocalSession(sessionId, rootDir = defaultRoot()) {
  try {
    const dir = join3(rootDir, "sessions");
    const file2 = join3(dir, `${sessionId}.jsonl`);
    const meta3 = join3(dir, `${sessionId}.meta.json`);
    let any3 = false;
    if (existsSync3(file2)) {
      await unlink(file2);
      any3 = true;
    }
    if (existsSync3(meta3)) {
      await unlink(meta3);
      any3 = true;
    }
    return any3;
  } catch {
    return false;
  }
}

