import { existsSync as existsSync5, readdirSync as readdirSync2 } from "fs";
import { join as join5 } from "path";
import { pathToFileURL } from "url";
var COMPONENTS_DIR2 = "components";
var TOOLS_DIR = "tools";
function getToolsDir() {
  return PATHS.tools;
}
function findToolFiles(dir) {
  if (!existsSync5(dir))
    return [];
  try {
    return readdirSync2(dir).filter((f) => f.endsWith(".ts") || f.endsWith(".js") || f.endsWith(".mjs")).map((f) => join5(dir, f));
  } catch {
    return [];
  }
}
async function loadToolFile(filepath) {
  try {
    const fileUrl = pathToFileURL(filepath).href;
    const module = await import(fileUrl);
    const toolDef = module.default || module.tool;
    if (!toolDef) {
      console.error(`Tool file ${filepath} has no default or 'tool' export`);
      return null;
    }
    if (!toolDef.name || !toolDef.tool) {
      console.error(`Tool file ${filepath} missing required fields (name, tool)`);
      return null;
    }
    return {
      name: toolDef.name,
      tool: toolDef.tool,
      description: toolDef.description || `Tool: ${toolDef.name}`
    };
  } catch (error50) {
    console.error(`Failed to load tool from ${filepath}:`, error50);
    return null;
  }
}
async function loadExternalTools() {
  const loadedTools = [];
  const userToolsDir = getToolsDir();
  for (const file2 of findToolFiles(userToolsDir)) {
    const tool2 = await loadToolFile(file2);
    if (tool2) {
      loadedTools.push(tool2);
    }
  }
  const localToolsDir = join5(process.cwd(), ".summon", COMPONENTS_DIR2, TOOLS_DIR);
  for (const file2 of findToolFiles(localToolsDir)) {
    const tool2 = await loadToolFile(file2);
    if (tool2) {
      loadedTools.push(tool2);
    }
  }
  return loadedTools;
}
async function registerExternalTools(options = {}) {
  const tools3 = await loadExternalTools();
  for (const tool2 of tools3) {
    if (globalToolRegistry.has(tool2.name)) {
      if (options.override) {
        console.log(`External tool '${tool2.name}' overriding existing tool`);
        globalToolRegistry.register(tool2);
      } else {
        console.log(`External tool '${tool2.name}' skipped - already registered (use override: true to replace)`);
      }
      continue;
    }
    globalToolRegistry.register(tool2);
  }
}
function listExternalToolFiles() {
  const files = [];
  const userToolsDir = getToolsDir();
  if (existsSync5(userToolsDir)) {
    files.push(...findToolFiles(userToolsDir).map((f) => `user:${f}`));
  }
  const localToolsDir = join5(process.cwd(), ".summon", COMPONENTS_DIR2, TOOLS_DIR);
  if (existsSync5(localToolsDir)) {
    files.push(...findToolFiles(localToolsDir).map((f) => `local:${f}`));
  }
  return files;
}

