// src/tools/resolver.ts
class ToolResolutionError extends Error {
  toolName;
  cause;
  constructor(message, toolName, cause) {
    super(message);
    this.toolName = toolName;
    this.cause = cause;
    this.name = "ToolResolutionError";
  }
}

class ToolNotFoundError extends ToolResolutionError {
  constructor(toolName) {
    super(`Tool '${toolName}' not found in registry`, toolName);
    this.name = "ToolNotFoundError";
  }
}
async function initializeToolResolver() {
  await loadExternalTools();
}
function resolveTool(toolName) {
  const registered = globalToolRegistry.get(toolName);
  if (!registered) {
    throw new ToolNotFoundError(toolName);
  }
  const builtinTools = ["financial_search", "web_search", "file_read", "file_write", "failing_tool"];
  const source = builtinTools.includes(toolName) ? "builtin" : "external";
  return {
    name: registered.name,
    tool: registered.tool,
    description: registered.description,
    source
  };
}
function resolveTools(toolNames) {
  return toolNames.map((name) => {
    try {
      return resolveTool(name);
    } catch (error50) {
      if (error50 instanceof ToolNotFoundError) {
        return null;
      }
      throw error50;
    }
  }).filter((tool2) => tool2 !== null);
}
function injectSecrets(toolConfig, env3) {
  const result = {};
  for (const [key, value] of Object.entries(toolConfig)) {
    if (typeof value === "string") {
      result[key] = injectSecretValue(value, env3);
    } else if (typeof value === "object" && value !== null) {
      result[key] = injectSecrets(value, env3);
    } else {
      result[key] = value;
    }
  }
  return result;
}
function injectSecretValue(value, env3) {
  const placeholderRegex = /\{\{(\w+)\}\}/g;
  return value.replace(placeholderRegex, (match, envVar) => {
    const secretValue = env3[envVar];
    if (secretValue === undefined) {
      console.warn(`[ToolResolver] Secret placeholder {{${envVar}}} not found in environment`);
      return match;
    }
    return secretValue;
  });
}

