  console.log("  [2] Continue without tools (limited results)");
  console.log("  [3] Cancel");
  console.log("");
  const rl = readline2.createInterface({
    input: process.stdin,
    output: process.stdout
  });
  const answer = await new Promise((resolve) => {
    rl.question("> ", resolve);
  });
  rl.close();
