// src/builtin/skills/git/index.ts
import { execSync } from "child_process";
init_zod();
async function execGit(args, cwd) {
  try {
    const stdout = execSync("git " + args.join(" "), {
      cwd: cwd || process.cwd(),
      encoding: "utf-8",
      maxBuffer: 10 * 1024 * 1024
    });
    return { stdout, stderr: "", code: 0 };
  } catch (error50) {
    const err = error50;
    return {
      stdout: err.stdout || "",
      stderr: err.stderr || String(error50),
      code: err.status || 1
    };
  }
}
var createGitStatusTool = () => {
  return new DynamicStructuredTool({
    name: "git_status",
    description: "Show working tree status (modified, staged, untracked files)",
    schema: exports_external.object({
      repo: exports_external.string().optional().describe("Repository path (default: current directory)")
    }),
    func: async ({ repo }) => {
      const result = await execGit(["status", "--porcelain"], repo);
      if (result.code !== 0) {
        return JSON.stringify({ error: result.stderr });
      }
      const lines = result.stdout.trim().split(`
`).filter(Boolean);
      const files = lines.map((line) => ({
        status: line.slice(0, 2).trim(),
        path: line.slice(3).trim()
      }));
      return JSON.stringify({
        repo: repo || process.cwd(),
        modified: files.filter((f) => f.status.includes("M")).length,
        staged: files.filter((f) => f.status.includes("A") || f.status.includes("D")).length,
        untracked: files.filter((f) => f.status.includes("??")).length,
        files,
        raw: result.stdout
      });
    }
  });
};
var createGitLogTool = () => {
  return new DynamicStructuredTool({
    name: "git_log",
    description: "Show recent commits with hash, author, date, and message",
    schema: exports_external.object({
      repo: exports_external.string().optional().describe("Repository path"),
      count: exports_external.number().optional().default(10).describe("Number of commits to show")
    }),
    func: async ({ repo, count = 10 }) => {
      const result = await execGit(["log", "--oneline", "-n", String(count), "--pretty=format:%h|%an|%ad|%s", "--date=short"], repo);
      if (result.code !== 0) {
        return JSON.stringify({ error: result.stderr });
      }
      const commits = result.stdout.trim().split(`
`).filter(Boolean).map((line) => {
        const [hash2, author, date7, ...msgParts] = line.split("|");
        return { hash: hash2, author, date: date7, message: msgParts.join("|") };
      });
      return JSON.stringify({
        repo: repo || process.cwd(),
        count: commits.length,
        commits
      });
    }
  });
};
var createGitDiffTool = () => {
  return new DynamicStructuredTool({
    name: "git_diff",
    description: "Show changes between commits, commit and working tree",
    schema: exports_external.object({
      repo: exports_external.string().optional().describe("Repository path"),
      cached: exports_external.boolean().optional().default(false).describe("Show staged changes only"),
      file: exports_external.string().optional().describe("Show diff for specific file")
    }),
    func: async ({ repo, cached: cached2 = false, file: file2 }) => {
      const args = ["diff"];
      if (cached2)
        args.push("--cached");
      if (file2)
        args.push(file2);
      const result = await execGit(args, repo);
      if (result.code !== 0) {
        return JSON.stringify({ error: result.stderr });
      }
      return JSON.stringify({
        repo: repo || process.cwd(),
        cached: cached2,
        file: file2,
        diff: result.stdout || "(no changes)"
      });
    }
  });
};
var createGitBranchTool = () => {
  return new DynamicStructuredTool({
    name: "git_branch",
    description: "List, create, or delete branches",
    schema: exports_external.object({
      repo: exports_external.string().optional().describe("Repository path"),
      create: exports_external.string().optional().describe("Create a new branch"),
      delete: exports_external.string().optional().describe("Delete a branch"),
      list: exports_external.boolean().optional().default(true).describe("List all branches")
    }),
    func: async ({ repo, create, delete: deleteBranch, list = true }) => {
      if (create) {
        const result = await execGit(["checkout", "-b", create], repo);
        return JSON.stringify({
          action: "create",
          branch: create,
          success: result.code === 0,
          output: result.stderr || result.stdout
        });
      }
      if (deleteBranch) {
        const result = await execGit(["branch", "-D", deleteBranch], repo);
        return JSON.stringify({
          action: "delete",
          branch: deleteBranch,
          success: result.code === 0,
          output: result.stderr || result.stdout
        });
      }
      if (list) {
        const result = await execGit(["branch", "-a", "--format=%(refname:short)"], repo);
        const branches = result.stdout.trim().split(`
`).filter(Boolean);
        const currentResult = await execGit(["rev-parse", "--abbrev-ref", "HEAD"], repo);
        const current = currentResult.stdout.trim();
        return JSON.stringify({
          repo: repo || process.cwd(),
          current,
          branches,
          count: branches.length
        });
      }
      return JSON.stringify({ error: "No action specified" });
    }
  });
};
var createGitSearchTool = () => {
  return new DynamicStructuredTool({
    name: "git_search",
    description: "Search for commits, files, or patterns in git history",
    schema: exports_external.object({
      repo: exports_external.string().optional().describe("Repository path"),
      query: exports_external.string().describe("Search pattern"),
      type: exports_external.enum(["commit", "file", "grep"]).optional().default("commit").describe("Search type"),
      count: exports_external.number().optional().default(20).describe("Max results")
    }),
    func: async ({ repo, query, type = "commit", count = 20 }) => {
      let args;
      if (type === "commit") {
        args = ["log", "--oneline", "--grep", query, "-n", String(count)];
      } else if (type === "file") {
        args = ["ls-files", query];
      } else {
        args = ["grep", "--oneline", "-n", query];
      }
      const result = await execGit(args, repo);
      if (result.code !== 0) {
        return JSON.stringify({ error: result.stderr });
      }
      const results = result.stdout.trim().split(`
`).filter(Boolean);
      return JSON.stringify({
        repo: repo || process.cwd(),
        query,
        type,
        count: results.length,
        results
      });
    }
  });
};
globalToolRegistry.register({
  name: "git_status",
  tool: createGitStatusTool(),
  description: "Show working tree status (modified, staged, untracked files)"
});
globalToolRegistry.register({
  name: "git_log",
  tool: createGitLogTool(),
  description: "Show recent commits with hash, author, date, and message"
});
globalToolRegistry.register({
  name: "git_diff",
  tool: createGitDiffTool(),
  description: "Show changes between commits, commit and working tree"
});
globalToolRegistry.register({
  name: "git_branch",
  tool: createGitBranchTool(),
  description: "List, create, or delete branches"
});
globalToolRegistry.register({
  name: "git_search",
  tool: createGitSearchTool(),
  description: "Search commits, files, or patterns in git history"
});

