      const severity = p.trigger.severity === "critical" ? "\uD83D\uDD25" : p.trigger.severity === "warning" ? "\u26A0\uFE0F" : "\u2139\uFE0F";
      console.log(`${icon} ${p.id.slice(0, 8)}... ${severity} ${p.type}`);
