prefsCmd.command("set").description("Set a preference value").option("--name <name>", "User name").option("--style <style>", "Response style (concise|detailed|exhaustive)").option("--tone <tone>", "Tone (formal|casual|professional)").option("--reasoning <mode>", "Reasoning display (hidden|brief|thorough)").option("--tables", "Enable tables").option("--no-tables", "Disable tables").option("--bullets", "Enable bullets").option("--no-bullets", "Disable bullets").option("--sources", "Require sources").option("--no-sources", "Do not require sources").option("--max-cost <amount>", "Max cost per run in USD").option("--max-time <minutes>", "Max time per run in minutes").action((options) => {
  let prefs = loadPreferences();
  if (options.name) {
    prefs.user.name = options.name;
  }
  if (options.style) {
    const valid = ["concise", "detailed", "exhaustive"];
    if (valid.includes(options.style)) {
      prefs = setStylePreference(prefs, "response_length", options.style);
    } else {
      console.error(`Invalid style. Use: ${valid.join(", ")}`);
      process.exit(1);
    }
  }
  if (options.tone) {
    const valid = ["formal", "casual", "professional"];
    if (valid.includes(options.tone)) {
      prefs = setStylePreference(prefs, "tone", options.tone);
    } else {
      console.error(`Invalid tone. Use: ${valid.join(", ")}`);
      process.exit(1);
    }
  }
  if (options.reasoning) {
    const valid = ["hidden", "brief", "thorough"];
    if (valid.includes(options.reasoning)) {
      prefs = setStylePreference(prefs, "reasoning", options.reasoning);
    } else {
      console.error(`Invalid reasoning mode. Use: ${valid.join(", ")}`);
      process.exit(1);
    }
  }
  if (options.tables !== undefined) {
    prefs = setFormatPreference(prefs, "use_tables", options.tables);
  }
  if (options.bullets !== undefined) {
    prefs = setFormatPreference(prefs, "use_bullets", options.bullets);
  }
  if (options.sources !== undefined) {
    prefs = setFormatPreference(prefs, "include_sources", options.sources);
  }
  if (options.maxCost) {
    const cost = parseFloat(options.maxCost);
    if (!isNaN(cost)) {
      prefs = setSafetyPreference(prefs, "max_cost_per_run", cost);
    }
  }
  if (options.maxTime) {
    const time4 = parseFloat(options.maxTime);
    if (!isNaN(time4)) {
      prefs = setSafetyPreference(prefs, "max_time_per_run", time4);
    }
  }
  if (savePreferences(prefs)) {
    console.log("\u2713 Preferences saved");
  } else {
    console.error("\u2717 Failed to save preferences");
    process.exit(1);
  }
});
